  `}function licensingGuides(){return[["Register with UNMC","For new graduates preparing first registration.","Documents needed|Application form|Fee payment|Examination|Certificate",["National ID","Academic transcript","Passport photo","School completion letter"],"https://unmc.ug/"],["Renew Your UNMC Licence","Annual renewal process, fees and deadline planning.","Check renewal window|Update CPD records|Pay renewal fee|Submit proof|Keep receipt",["Current licence","CPD evidence","Payment receipt","Contact details"],"https://unmc.ug/"],["Get Qualifications Recognised Abroad","Prepare UK NMC, AHPRA, DHA and SCFHS documentation.","Choose destination|Verify documents|Book English test|Request council letters|Submit portal profile",["Transcript","Good standing letter","Certificate of registration","English test"],"https://www.nmc.org.uk/"],["Good Standing Letter from UNMC","What it is, why you need it and how to request it.","Confirm eligibility|Gather registration proof|Pay request fee|Submit application|Collect letter",["Registration certificate","Licence copy","Payment proof","Destination body details"],"https://unmc.ug/"]]}function renderLicensingGuides(){return`
